 static SettlementController C=>Object.FindAnyObjectByType<SettlementController>();
 static void Check(bool b,string m){if(!b)throw new Exception(m);}
 static async Task Tap(Button b){await Task.Delay(100);Check(b&&b.IsActive()&&b.IsInteractable(),"Unavailable "+b?.name);Canvas.ForceUpdateCanvases();var r=(RectTransform)b.transform;var e=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(b.GetComponentInParent<Canvas>().worldCamera,r.TransformPoint(r.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(e,hits);Check(hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==b,"Blocked "+b.name+" by "+hits.FirstOrDefault().gameObject?.name);ExecuteEvents.Execute(b.gameObject,e,ExecuteEvents.pointerClickHandler);await Task.Delay(150);}
 static void Fits(Text t){Canvas.ForceUpdateCanvases();Check(t.preferredHeight<=t.rectTransform.rect.height+1,"Clipped "+t.name+" "+t.preferredHeight+" > "+t.rectTransform.rect.height+" : "+t.text);}
 static async Task Shot(string name){ScreenCapture.CaptureScreenshot(Shots+name+".png");await Task.Delay(350);}
 static async Task Load(int count=2,bool bags=false){
  var catalog=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Settlement/SettlementScreen.prefab").GetComponent<SettlementController>();
  var s=JsonUtility.FromJson<CampaignSaveData>(File.ReadAllText("Temp/TutorialClaritySave/resume.json"));s.IntroductionStep=10;s.Visitor=new SavedVisitor();s.Opening.Enabled=false;s.Opening.Complete=false;s.Opening.NightHeard=false;s.Opening.NightChoice=0;s.Rest=Array.Empty<SavedRest>();s.Craft=Array.Empty<SavedCraft>();s.Cooking=Array.Empty<SavedCooking>();s.SideRoomConnected=s.SideRoomReady=true;s.Development.Tools=true;s.Development.Research=true;s.Development.Workbench=true;
  // The fixture has already visited the mall, so its next visit is the awake site board; mark the one-time board intro as seen (save v13) so it does not cover these checks.
  s.Version=CampaignPersistence.CurrentVersion;s.SiteBoards=new[]{new SavedSiteBoard{Id="mall",Remembered="",IntroShown=true}};
  var pair=new[]{"scout","medic"};var candidates=count==2?pair.Select(id=>catalog.Roster.Candidates.First(c=>c.Id==id)):catalog.Roster.Candidates.Take(count);
  s.Members=candidates.Select(d=>new SavedMember{Id=d.Id,Name=d.DisplayName,Role=d.RoleTitle,Description=d.Description,Health=d.Health-1,Maximum=d.Health,Aim=d.Aim,Capacity=d.BagCapacity,Bag=bags?new[]{new SavedCount{Id="bandage",Count=2},new SavedCount{Id="water",Count=2},new SavedCount{Id="ration",Count=2}}:Array.Empty<SavedCount>()}).ToArray();
  CampaignPersistence.Prepare(s,catalog);SceneManager.LoadScene("Settlement");await Task.Delay(700);
 }
