 public static async Task<string> Resolutions(){
  const System.Reflection.BindingFlags F=System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;
  var assembly=typeof(Editor).Assembly;var st=assembly.GetType("UnityEditor.GameViewSizes");var singleton=typeof(ScriptableSingleton<>).MakeGenericType(st);var sizes=singleton.GetProperty("instance",System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.Static).GetValue(null);var group=st.GetMethod("GetGroup",F).Invoke(sizes,new[]{st.GetProperty("currentGroupType",F).GetValue(sizes)});var view=EditorWindow.GetWindow(assembly.GetType("UnityEditor.GameView"));var selected=view.GetType().GetProperty("selectedSizeIndex",F);int original=(int)selected.GetValue(view);var results=new List<string>();
  try{foreach(var wh in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1200),new Vector2Int(2560,1080)}){
   var sizeType=assembly.GetType("UnityEditor.GameViewSize");var kind=assembly.GetType("UnityEditor.GameViewSizeType");int count=(int)group.GetType().GetMethod("GetTotalCount",F).Invoke(group,null),index=-1;
   for(int i=0;i<count;i++){var size=group.GetType().GetMethod("GetGameViewSize",F).Invoke(group,new object[]{i});if((int)sizeType.GetProperty("width",F).GetValue(size)==wh.x&&(int)sizeType.GetProperty("height",F).GetValue(size)==wh.y){index=i;break;}}
   if(index<0){var size=Activator.CreateInstance(sizeType,F,null,new object[]{Enum.ToObject(kind,1),wh.x,wh.y,"Review "+wh.x+"x"+wh.y},null);group.GetType().GetMethod("AddCustomSize",F).Invoke(group,new[]{size});index=count;}
   selected.SetValue(view,index);view.Repaint();await Task.Delay(400);Check(Screen.width==wh.x&&Screen.height==wh.y,"Resolution not applied");
   await Load();C.Opening.State.Enabled=true;C.WorkPanel.Open();await Tap(C.WorkPanel.Rows[0].Button);Fits(G.Title);Fits(G.Instruction);await Shot("74-rest-"+wh.x+"x"+wh.y);await Tap(G.Target);Check(C.WorkPanel.Orders.Count==1,"Guided rest failed at "+wh);C.WorkPanel.Cancel(C.Campaign.Party.First());
   C.Opening.State.Enabled=false;C.PackingPanel.Open(C.Campaign.Party.ToArray(),C.ExpeditionPanel.Destinations.First(d=>d.Id=="mall"),null);await Tap(C.PackingPanel.Ready);Fits(C.PackingPanel.DepartureNotice);Fits(C.PackingPanel.ReviewDestination);await Shot("75-review-"+wh.x+"x"+wh.y);await Tap(C.PackingPanel.ReviewBack);C.PackingPanel.Close();
   await Load(6,true);var a=C.ArrivalPanel;a.Begin(C.Campaign.Party.ToArray(),C.ExpeditionPanel.Destinations.First(d=>d.Id=="mall"));for(int i=0;i<70&&a.InTransit;i++)await Task.Delay(100);a.FieldBags.Open(0);await Tap(a.FieldBags.LeftRows.First(r=>r.Label.text=="붕대").Button);await Tap(a.FieldBags.RightCards.Last().Button);await Shot("76-six-bags-"+wh.x+"x"+wh.y);results.Add(wh.x+"x"+wh.y);
  }}finally{selected.SetValue(view,original);view.Repaint();}
  return "PASS actual UI raycasts and text fit for rest + tutorial, travel review, 6-person bag last-recipient transfer at "+string.Join(", ",results)+"; previous Game View size restored.";
 }
 [Serializable] class Envelope {public string Magic,Payload,Hash;}
 static string Encode(CampaignSaveData data){string payload=JsonUtility.ToJson(data);using(var sha=System.Security.Cryptography.SHA256.Create())return JsonUtility.ToJson(new Envelope{Magic="NEIGHBOR-NOT-SAVE",Payload=payload,Hash=Convert.ToBase64String(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(payload)))});}
 public static async Task<string> SaveFailures(){
  await Load(6,true);var owner=C;var saved=CampaignPersistence.Capture(C);string path=Path.GetFullPath("Temp/UIAuditSlots");Directory.CreateDirectory(path);CampaignSaveStore.TestDirectory=path;var files=Enumerable.Range(0,3).Select(i=>CampaignSaveStore.SlotPath(i)).ToArray();var original=files.Select(f=>File.Exists(f)?File.ReadAllBytes(f):null).ToArray();
  try{
   Check(CampaignSaveStore.Write(0,saved,C,out var error),error);File.WriteAllText(files[1],"{ invalid-save }");var future=JsonUtility.FromJson<CampaignSaveData>(JsonUtility.ToJson(saved));future.Version=999;File.WriteAllText(files[2],Encode(future));
   C.GameMenu.Open();await Tap(C.GameMenu.Load);var p=C.GameMenu.SavePanel;await Tap(p.Slots[1]);Check(!p.Action.IsInteractable()&&p.SlotDetails[1].text.Length>0,"Corrupt save selectable");await Tap(p.Slots[2]);Check(!p.Action.IsInteractable()&&p.SlotDetails[2].text.Contains("버전"),"Future version must explain failure");foreach(var t in p.SlotDetails)Fits(t);await Shot("77-load-errors");
   await Tap(p.Slots[0]);await Tap(p.Action);Check(p.Review.activeSelf,"Load confirmation absent");File.WriteAllText(files[0],"file changed after confirmation");await Tap(p.Confirm);Check(C==owner&&!p.Review.activeSelf&&!p.Action.IsInteractable()&&p.Hint.text.Length>0,"Stale save confirmation advanced scene");Fits(p.Hint);await Shot("78-load-changed-file");await Tap(p.Back);C.GameMenu.Close();
   Check(CampaignSaveStore.Write(0,saved,C,out error),error);var loaded=CampaignSaveStore.Read(0,C);Check(loaded.CanLoad,loaded.Error);Check(loaded.Data.Members.Length==6&&loaded.Data.Members.All(m=>m.Bag.Length==3),"Six-person save lost bags");
   var before=File.ReadAllBytes(files[0]);saved.Members[0].Health=-1;Check(!CampaignSaveStore.Write(0,saved,C,out error)&&File.ReadAllBytes(files[0]).SequenceEqual(before),"Invalid save replaced valid record");
  }finally{for(int i=0;i<files.Length;i++){if(original[i]!=null)File.WriteAllBytes(files[i],original[i]);else if(File.Exists(files[i]))File.Delete(files[i]);}CampaignSaveStore.TestDirectory=null;}
  return "PASS corrupt/future-version UI explains failure and blocks load; file changed after confirmation is re-read; invalid overwrite preserves valid file; six-person bags survive disk write/read. Test slots restored, player saves untouched.";
 }
